        self._init_weights(self.actor, gain=1.0)
        self._init_weights(self.critic, gain=1.0)
        # Lower gain on final policy layer for smaller initial outputs
        for mod in self.actor:
            if isinstance(mod, nn.Linear) and mod.out_features == num_actions:
                nn.init.orthogonal_(mod.weight, gain=0.01)
                nn.init.zeros_(mod.bias)
